# owner: platform
import unittest

from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts
from rosterkit.models import Student


def make(last, section, email="x@school.org"):
    return Student("1", last, "Amy", section, email)


class ContactTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = format_contacts([
            make("Zed", "B", "z@school.org"),
            make("Longname", "10A", "l@school.org")
        ])
        self.assertEqual(rows, [
            "Longname, Amy  10A  l@school.org",
            "Zed, Amy       B    z@school.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as caught:
            format_contacts([make("Zed", "B", None)])
        self.assertIn("Zed, Amy", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
